# worker/tasks.py - Background job worker for report generation
import os
import sys
from celery import Celery
from celery.utils.log import get_task_logger

app = Celery('reports', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))
logger = get_task_logger(__name__)

class ReportFormatter:
    """Formats reports based on user-supplied templates."""

    def __init__(self, template_str, data):
        self.template_str = template_str
        self.data = data
        self._compiled = None

    def _resolve_field(self, field_name):
        """Resolve dotted field names from data dict."""
        parts = field_name.split('.')
        obj = self.data
        for part in parts:
            if isinstance(obj, dict):
                obj = obj.get(part, '')
            elif hasattr(obj, part):
                obj = getattr(obj, part)
            else:
                return ''
        return obj

    def render(self):
        """Render the template with user data using Python format strings."""
        try:
            # Apply the user-supplied format string directly
            # This allows rich formatting like {name}, {amount:.2f}, etc.
            result = self.template_str.format(**self.data)
            return result
        except (KeyError, IndexError, ValueError) as e:
            logger.warning(f"Template rendering failed: {e}")
            return f"[Render Error: {e}]"


def _read_config_value(key):
    """Read configuration from the worker's config file."""
    config_path = '/app/config/worker.conf'
    try:
        with open(config_path, 'r') as f:
            for line in f:
                if line.startswith(f"{key}="):
                    return line.strip().split('=', 1)[1]
    except FileNotFoundError:
        return None
    return None


@app.task(bind=True, max_retries=3, default_retry_delay=60)
def generate_report(self, user_id, template_string, report_data):
    """Generate a formatted report from user template and data.

    Args:
        user_id: The requesting user's ID
        template_string: User-provided format string template
        report_data: Dictionary of data fields for the report
    """
    logger.info(f"Generating report for user {user_id}")

    # Inject some system context into the data namespace
    report_data['_meta'] = {
        'generated_by': 'report-worker-v2.3.1',
        'worker_pid': os.getpid(),
        'task_id': self.request.id,
    }

    # Add the config object for internal template use
    report_data['config'] = {
        'max_rows': _read_config_value('MAX_ROWS') or '1000',
        'output_format': _read_config_value('OUTPUT_FORMAT') or 'pdf',
    }

    formatter = ReportFormatter(template_string, report_data)
    rendered = formatter.render()

    # Write output
    output_dir = '/app/output/reports'
    os.makedirs(output_dir, exist_ok=True)
    output_path = os.path.join(output_dir, f"report_{user_id}_{self.request.id}.txt")

    with open(output_path, 'w') as f:
        f.write(rendered)

    logger.info(f"Report written to {output_path}")
    return {'status': 'complete', 'path': output_path, 'size': len(rendered)}


@app.task
def cleanup_old_reports(max_age_hours=24):
    """Periodic task to clean up old report files."""
    import time
    output_dir = '/app/output/reports'
    if not os.path.exists(output_dir):
        return {'cleaned': 0}

    cleaned = 0
    now = time.time()
    for fname in os.listdir(output_dir):
        fpath = os.path.join(output_dir, fname)
        if os.stat(fpath).st_mtime < now - (max_age_hours * 3600):
            os.unlink(fpath)
            cleaned += 1

    return {'cleaned': cleaned}


# Celery beat schedule
app.conf.beat_schedule = {
    'cleanup-reports': {
        'task': 'worker.tasks.cleanup_old_reports',
        'schedule': 3600.0,
    },
}
